using namespace std;
using ll=long long ;
const int mod = 1000000007;

struct Mod {
	int num;
	Mod() : num(0) {}
	Mod(ll n) : num((n%mod+mod)%mod) {}
	Mod(int n) : Mod((ll)n) {}
	operator int() const { return num; }
};
Mod operator+(Mod a, Mod b) { return Mod((a.num+b.num)%mod); }
Mod operator-(Mod a, Mod b) { return Mod((mod+a.num-b.num)%mod); }
Mod operator*(Mod a, Mod b) { return Mod((ll)a.num*b.num%mod); }
Mod operator^(Mod a, int n) {
	Mod res=1;
	while(n){
		if(n&1) res=res*a;
		a=a*a;
		n>>=1;
	}
	return res;
}
Mod inv(Mod a) { return a^(mod-2); }
Mod operator/(Mod a, Mod b) { return a*inv(b); }
Mod operator+=(Mod& a, Mod b) { return a=a+b; }
Mod operator-=(Mod& a, Mod b) { return a=a-b; }
Mod operator*=(Mod& a, Mod b) { return a=a*b; }
Mod operator/=(Mod& a, Mod b) { return a=a/b; }

map<int,int> mp;

void init(vector<vector<Mod>>& pers) {
	vector<int> v = {0,0,0,1,1,1};
	int id=0;
	do {
		int tt=0;
		for(int k=0;k<6;++k) if(v[k]) tt^=(1<<k);
		mp[tt]=id++;
	} while(next_permutation(v.begin(),v.end()));
	int N; cin>>N;
	int s=3-(N+1)/2;
	for(int i=0;i<s;++i) pers[i][i]=Mod(1);
	for(int i=s;i<s+N;++i) {
		for(int j=s;j<s+N;++j) {
			int p; cin>>p;
			pers[i][j]=Mod(p)/Mod(100);
		}
	}
	for(int i=s+N;i<6;++i) pers[i][i]=Mod(1);
}

vector<Mod> solve(const vector<vector<Mod>>& pers, int al=0) {
	vector<Mod> l_nums(1<<20);
	for(int xx=0; xx<(1<<18); ++xx) {
		Mod per=1;
		int haves[3][6] = {0};
		for(int i=0;i<3;++i) {
			for(int j=0;j<6;++j) {
				int k=i*6+j;
				if(xx>>k & 1) {
					haves[i][j]=1;
					per *= pers[al+i][j];
				} else {
					per *= (Mod(1)-pers[al+i][j]);
				}
			}
		}
		int flags=0;
		for(int i=0;i<6;++i) if(haves[0][i])
		for(int j=0;j<6;++j) if(haves[1][j] && i!=j)
		for(int k=0;k<6;++k) if(haves[2][k] && i!=k && j!=k) {
			int anum = (1<<i) ^ (1<<j) ^ (1<<k);
			flags |= 1<<mp[anum];
		}
		l_nums[flags] += per;
	}
	return l_nums;
}

int main() {
	ios::sync_with_stdio(false);
	vector<vector<Mod>> pers(6, vector<Mod>(6));
	init(pers);
	auto u_nums = solve(pers,0);
	auto d_nums = solve(pers,3);
	for(int x=1; x<(1<<20); x<<=1) {
		for(int i=0; i<(1<<20); ++i) {
			if((i&x)==0) d_nums[i^x] += d_nums[i];
		}
	}
	Mod ans=0;
	for(int i=0; i<(1<<20); ++i) {
		if(u_nums[i].num) {
			int need=0;
			for(int x=0;x<20;++x) if(i>>x & 1) need |= 1<<(19-x);
			Mod nans = u_nums[i] * (Mod(1) - d_nums[((1<<20)-1)^need]);
			ans += nans;
		}
	}
	cout << ans.num << endl;
	return 0;
}
